  // Nothing else (process, require, global, …) is in scope.
  const sandbox = vm.createContext(
    Object.freeze({ ctx: context })
  );

  return vm.runInNewContext(
    `(${rule})`,   // wrap in parens so bare objects `{…}` parse as expressions
