/**
 * app.js — POST /check endpoint with a safe, sandboxed rule evaluator.
 *
 * WHY NOT new Function() / eval()
 * ────────────────────────────────
 * docs/RULES_ENGINE.md suggests:
 *
 *   return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req);
