// Tokeniser
// ─────────────────────────────────────────────────────────────────────────────

const TT = {
  NUMBER: 'NUMBER',
  STRING: 'STRING',
  BOOLEAN: 'BOOLEAN',
  NULL: 'NULL',
  IDENT: 'IDENT',
  OP: 'OP',
  DOT: 'DOT',
  LPAREN: 'LPAREN',
  RPAREN: 'RPAREN',
  EOF: 'EOF',
};

const OPERATORS = new Set([
  '===', '!==', '==', '!=', '<=', '>=', '&&', '||',
  '<', '>', '+', '-', '*', '/', '%',
]);

/**
 * Tokenise `src` into an array of {type, value} tokens.
 * Throws SyntaxError on unrecognised characters.
 */
function tokenise(src) {
  const tokens = [];
  let i = 0;

  while (i < src.length) {
    // Skip whitespace
    if (/\s/.test(src[i])) { i++; continue; }

