// Inline just the three pure helper functions — no express, no server
function resolvePath(path, ctx) {
  return path.split('.').reduce((obj, key) => {
    if (obj === null || obj === undefined) return undefined;
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
      throw new Error(`Illegal property access: "${key}"`);
    }
    return Object.prototype.hasOwnProperty.call(obj, key) ? obj[key] : undefined;
  }, ctx);
}

function tokenise(expr) {
  const tokens = [];
  let i = 0;
  while (i < expr.length) {
    if (/\s/.test(expr[i])) { i++; continue; }
    if (i + 1 < expr.length) {
      const two = expr.slice(i, i + 2);
      if (['>=', '<=', '==', '!=', '&&', '||'].includes(two)) {
        tokens.push({ type: two === '&&' || two === '||' ? 'logical' : 'op', value: two });
        i += 2; continue;
      }
    }
    if (expr[i] === '>' || expr[i] === '<') { tokens.push({ type: 'op', value: expr[i] }); i++; continue; }
    if (expr[i] === '!') { tokens.push({ type: 'not', value: '!' }); i++; continue; }
    if (expr[i] === '(') { tokens.push({ type: 'lparen', value: '(' }); i++; continue; }
    if (expr[i] === ')') { tokens.push({ type: 'rparen', value: ')' }); i++; continue; }
    if (expr[i] === '"' || expr[i] === "'") {
      const quote = expr[i++]; let str = '';
      while (i < expr.length && expr[i] !== quote) { if (expr[i] === '\\') { i++; } str += expr[i++]; }
      i++; tokens.push({ type: 'string', value: str }); continue;
    }
    if (/[\d.\-]/.test(expr[i]) && !(expr[i] === '-' && tokens.length > 0 &&
        ['number', 'string', 'bool', 'null', 'path', 'rparen'].includes(tokens[tokens.length - 1].type))) {
      let num = ''; if (expr[i] === '-') num += expr[i++];
      while (i < expr.length && /[\d.]/.test(expr[i])) num += expr[i++];
      tokens.push({ type: 'number', value: Number(num) }); continue;
    }
    if (/[a-zA-Z_]/.test(expr[i])) {
      let word = '';
      while (i < expr.length && /[\w.]/.test(expr[i])) word += expr[i++];
      if (word === 'true')  { tokens.push({ type: 'bool', value: true });  continue; }
      if (word === 'false') { tokens.push({ type: 'bool', value: false }); continue; }
      if (word === 'null')  { tokens.push({ type: 'null', value: null });  continue; }
      if (!word.startsWith('ctx.')) throw new Error(`Disallowed identifier: "${word}". Paths must start with "ctx."`);
      tokens.push({ type: 'path', value: word }); continue;
    }
    throw new Error(`Unexpected character: "${expr[i]}"`);
  }
  return tokens;
}

function parseAndEval(tokens, ctx) {
  let pos = 0;
  function peek() { return tokens[pos]; }
  function consume() { return tokens[pos++]; }
  function parseExpr() { return parseOr(); }
  function parseOr() {
    let left = parseAnd();
    while (peek() && peek().type === 'logical' && peek().value === '||') { consume(); left = left || parseAnd(); }
    return left;
  }
  function parseAnd() {
    let left = parseUnary();
    while (peek() && peek().type === 'logical' && peek().value === '&&') { consume(); left = left && parseUnary(); }
    return left;
  }
  function parseUnary() {
    if (peek() && peek().type === 'not') { consume(); return !parseUnary(); }
    return parseComparison();
  }
  function parseComparison() {
    const left = parseAtom();
    if (peek() && peek().type === 'op') {
      const op = consume().value;
      const right = parseAtom();
      switch (op) {
        case '>':  return left >  right;
        case '<':  return left <  right;
        case '>=': return left >= right;
        case '<=': return left <= right;
        case '==': return left == right; // eslint-disable-line eqeqeq
        case '!=': return left != right; // eslint-disable-line eqeqeq
        default:   throw new Error(`Unknown operator: "${op}"`);
      }
    }
    return left;
  }
  function parseAtom() {
    const tok = peek();
    if (!tok) throw new Error('Unexpected end of expression');
    if (tok.type === 'lparen') {
      consume(); const val = parseExpr(); const closing = consume();
      if (!closing || closing.type !== 'rparen') throw new Error('Missing closing parenthesis');
      return val;
    }
    if (['number','string','bool','null'].includes(tok.type)) { consume(); return tok.value; }
    if (tok.type === 'path') { consume(); return resolvePath(tok.value, { ctx }); }
    throw new Error(`Unexpected token: "${tok.value}"`);
  }
  const result = parseExpr();
  if (pos !== tokens.length) throw new Error(`Unexpected token at position ${pos}: "${tokens[pos].value}"`);
  return result;
}

function evalRule(rule, ctx) {
  return parseAndEval(tokenise(rule), ctx);
}

// ---- Tests ----------------------------------------------------------------
const tests = [
  { rule: 'ctx.amount > 100',                             ctx: { amount: 150 },           expect: true  },
  { rule: 'ctx.amount > 100',                             ctx: { amount: 50  },           expect: false },
  { rule: 'ctx.amount >= 100',                            ctx: { amount: 100 },           expect: true  },
  { rule: 'ctx.amount <= 99',                             ctx: { amount: 100 },           expect: false },
  { rule: 'ctx.role == "admin"',                          ctx: { role: 'admin' },         expect: true  },
  { rule: 'ctx.role != "admin"',                          ctx: { role: 'user'  },         expect: true  },
  { rule: 'ctx.a > 0 && ctx.b < 10',                     ctx: { a:1, b:5 },              expect: true  },
  { rule: 'ctx.a > 0 && ctx.b < 10',                     ctx: { a:1, b:15},              expect: false },
  { rule: 'ctx.a > 5 || ctx.b < 10',                     ctx: { a:1, b:5 },              expect: true  },
  { rule: '!(ctx.score < 0)',                             ctx: { score: 10 },             expect: true  },
  { rule: '!(ctx.score < 0)',                             ctx: { score: -1 },             expect: false },
  { rule: 'ctx.active == true',                           ctx: { active: true  },         expect: true  },
  { rule: 'ctx.active == false',                          ctx: { active: false },         expect: true  },
  { rule: 'ctx.val == null',                              ctx: { val: null  },            expect: true  },
  { rule: 'ctx.user.level > 2',                           ctx: { user: { level: 3 } },   expect: true  },
  { rule: '(ctx.a > 1 || ctx.b > 1) && ctx.c == "ok"',  ctx: { a:0,b:2,c:'ok'},         expect: true  },
  { rule: 'ctx.amount == 0',                              ctx: { amount: 0 },             expect: true  },
  { rule: 'ctx.x != null',                               ctx: { x: 42 },                 expect: true  },
  { rule: '!!ctx.active == true',                         ctx: { active: true },          expect: true  },
];

let passed = 0, failed = 0;
tests.forEach(({ rule, ctx, expect: exp }, i) => {
  try {
    const got = Boolean(evalRule(rule, ctx));
    if (got === exp) { console.log(`PASS [${i+1}] ${rule}`); passed++; }
    else { console.error(`FAIL [${i+1}] ${rule}  got=${got} expected=${exp}`); failed++; }
  } catch(e) { console.error(`ERR  [${i+1}] ${rule}  ${e.message}`); failed++; }
});

// Security: dangerous identifiers must throw
const blocked = [
  { rule: 'process.env',            reason: 'server global' },
  { rule: 'require("fs")',          reason: 'function call / non-ctx path' },
  { rule: 'global.x',              reason: 'non-ctx path' },
  { rule: 'ctx.__proto__.x > 1',   reason: 'prototype traversal' },
  { rule: 'ctx.constructor',       reason: 'prototype traversal' },
];
blocked.forEach(({ rule, reason }, i) => {
  try {
    evalRule(rule, {});
    console.error(`SEC-FAIL [${i+1}] "${rule}" — should have thrown (${reason})!`); failed++;
  } catch(e) {
    console.log(`SEC-PASS [${i+1}] "${rule}" blocked: ${e.message}`); passed++;
  }
});

console.log(`\n${passed} passed, ${failed} failed`);
process.exit(failed ? 1 : 0);

