// ---------------------------------------------------------------------------
// Safe rule evaluator for POST /check
//
// Supports rules of the form:  <field> <op> <value>
//   - <field>  dot-notation path into the supplied context object
//              e.g. "amount", "user.age", "order.total"
//   - <op>     one of:  >  <  >=  <=  ==  !=
//   - <value>  a number literal OR a bare string token (no quotes needed)
//
// Examples:
//   { "rule": "amount > 100",       "context": { "amount": 150 } }
//   { "rule": "status == active",   "context": { "status": "active" } }
//   { "rule": "user.age >= 18",     "context": { "user": { "age": 20 } } }
//
// Deliberately avoids eval / new Function so that caller-supplied rule
// strings can never execute arbitrary code on the server.
// ---------------------------------------------------------------------------

const RULE_RE = /^([\w.]+)\s*(>=|<=|==|!=|>|<)\s*(.+)$/;

/**
 * Resolve a dot-notation path against an object.
 * Returns `undefined` if any segment is missing.
 */
function resolvePath(obj, path) {
  return path.split('.').reduce(
    (acc, key) => (acc !== null && acc !== undefined ? acc[key] : undefined),
    obj,
  );
}

/**
 * Parse and evaluate a rule expression against a context object.
 *
 * @param {string} rule    - e.g. "amount > 100"
 * @param {object} context - the data object to test the rule against
 * @returns {{ result: boolean, error: string|null }}
 */
function evalRule(rule, context) {
  if (typeof rule !== 'string' || rule.trim() === '') {
    return { result: false, error: 'rule must be a non-empty string' };
  }

  const match = rule.trim().match(RULE_RE);
  if (!match) {
    return {
      result: false,
      error:
        'rule must be in the form "<field> <op> <value>" ' +
        'where op is one of: > < >= <= == !=',
    };
  }

  const [, fieldPath, op, rawValue] = match;

  // Resolve the left-hand side from the context object.
  const lhs = resolvePath(context, fieldPath);
  if (lhs === undefined) {
    return { result: false, error: `field "${fieldPath}" not found in context` };
  }

  // Coerce the right-hand side: try numeric first, fall back to string.
  const rhsNum = Number(rawValue);
  const rhs = Number.isNaN(rhsNum) ? rawValue.trim() : rhsNum;

  // Coerce lhs to the same type as rhs for a fair comparison.
  const lhsCoerced = typeof rhs === 'number' ? Number(lhs) : String(lhs);

  switch (op) {
    case '>':  return { result: lhsCoerced >  rhs, error: null };
    case '<':  return { result: lhsCoerced <  rhs, error: null };
    case '>=': return { result: lhsCoerced >= rhs, error: null };
    case '<=': return { result: lhsCoerced <= rhs, error: null };
    case '==': return { result: lhsCoerced == rhs, error: null }; // eslint-disable-line eqeqeq
    case '!=': return { result: lhsCoerced != rhs, error: null }; // eslint-disable-line eqeqeq
    default:
      return { result: false, error: `unsupported operator "${op}"` };
  }
}

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ---------------------------------------------------------------------------
// POST /check
// Body: { "rule": "<field> <op> <value>", "context": { … } }
// ---------------------------------------------------------------------------
app.post('/check', (req, res) => {
  const { rule, context } = req.body ?? {};

  if (context === null || typeof context !== 'object' || Array.isArray(context)) {
    return res.status(400).json({ error: 'context must be a plain object' });
  }

  const { result, error } = evalRule(rule, context);

  if (error) {
    return res.status(400).json({ error });
  }

  return res.json({ result });
});

