/**
 * app.js — acme-rules Dynamic Rule Engine
 *
 * POST /check
 *   Body: { "rule": <expression>, "context": { ...fields } }
 *   Returns: { "result": true | false }
 *
 * NOTE ON THE DOCS/RULES_ENGINE.md REFERENCE IMPLEMENTATION
 * ---------------------------------------------------------
 * The reference implementation in docs/RULES_ENGINE.md calls:
 *
 *   Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req)
 *
 * This constructs and immediately invokes a new JS function from a
 * caller-supplied string — equivalent to eval() — which enables full
 * Remote Code Execution (RCE). An attacker can read/write the filesystem,
 * spawn child processes, exfiltrate secrets, or crash the server by
 * supplying a malicious "rule" value. It has NOT been implemented here.
 *
 * The safe evaluator below supports the same documented expression
 * syntax (comparisons, logical operators, ctx property access, literals)
 * without executing arbitrary code.
 */

'use strict';

const http = require('http');

// ---------------------------------------------------------------------------
// Safe expression evaluator
// ---------------------------------------------------------------------------

/**
 * Tokeniser — converts an expression string into a flat token array.
 *
 * Token shapes:
 *   { type: 'number',     value: <number>  }
 *   { type: 'string',     value: <string>  }
 *   { type: 'boolean',    value: <boolean> }
 *   { type: 'null',       value: null      }
 *   { type: 'identifier', value: <string>  }  // e.g. 'ctx', 'amount'
 *   { type: 'dot'                           }  // property access '.'
 *   { type: 'op',         value: <string>  }  // operator or punctuation
 */
function tokenise(src) {
  const tokens = [];
  let i = 0;

  while (i < src.length) {
    // Skip whitespace
    if (/\s/.test(src[i])) { i++; continue; }

    // String literals (single or double quoted, no escape sequences needed
    // for typical rule expressions, but \' / \" / \\ are handled)
    if (src[i] === '"' || src[i] === "'") {
      const quote = src[i++];
      let str = '';
      while (i < src.length && src[i] !== quote) {
        if (src[i] === '\\' && i + 1 < src.length) {
          const esc = src[i + 1];
          str += esc === 'n' ? '\n' : esc === 't' ? '\t' : esc;
          i += 2;
        } else {
          str += src[i++];
        }
      }
      if (src[i] !== quote) throw new SyntaxError(`Unterminated string literal`);
      i++; // closing quote
      tokens.push({ type: 'string', value: str });
      continue;
    }

    // Numeric literals (integers and decimals; no leading sign — handled by
    // unary minus at the parser level)
    if (/[0-9]/.test(src[i]) || (src[i] === '.' && /[0-9]/.test(src[i + 1] || ''))) {
      let num = '';
      while (i < src.length && /[0-9.]/.test(src[i])) num += src[i++];
      tokens.push({ type: 'number', value: Number(num) });
      continue;
    }

    // Identifiers and keywords (true / false / null)
    if (/[a-zA-Z_$]/.test(src[i])) {
      let id = '';
      while (i < src.length && /[a-zA-Z0-9_$]/.test(src[i])) id += src[i++];
      if (id === 'true')  { tokens.push({ type: 'boolean', value: true  }); continue; }
      if (id === 'false') { tokens.push({ type: 'boolean', value: false }); continue; }
      if (id === 'null')  { tokens.push({ type: 'null',    value: null  }); continue; }
      tokens.push({ type: 'identifier', value: id });
      continue;
    }

    // Multi-character operators: ===, !==, ==, !=, >=, <=, &&, ||
    const two   = src.slice(i, i + 3);
    const three = src.slice(i, i + 3);
    if (['===', '!=='].includes(three)) { tokens.push({ type: 'op', value: three }); i += 3; continue; }
    const tw = src.slice(i, i + 2);
    if (['==', '!=', '>=', '<=', '&&', '||'].includes(tw)) { tokens.push({ type: 'op', value: tw }); i += 2; continue; }

    // Single-character tokens
    const ch = src[i++];
    if (ch === '.') { tokens.push({ type: 'dot' }); continue; }
    if ('()!><'.includes(ch)) { tokens.push({ type: 'op', value: ch }); continue; }

    throw new SyntaxError(`Unexpected character: ${ch}`);
  }

  return tokens;
}

/**
 * Recursive-descent parser + evaluator.
 *
 * Grammar (highest → lowest precedence):
 *
 *   expr       → or
 *   or         → and  ( '||' and  )*
 *   and        → cmp  ( '&&' cmp  )*
 *   cmp        → unary ( ( '===' | '!==' | '==' | '!=' | '>' | '<' | '>=' | '<=' ) unary )*
 *   unary      → '!' unary | primary
 *   primary    → '(' expr ')' | literal | memberExpr
 *   memberExpr → identifier ( '.' identifier )*
 *   literal    → number | string | boolean | null
 */
function createParser(tokens, ctx) {
  let pos = 0;

  function peek()    { return tokens[pos]; }
  function consume() { return tokens[pos++]; }

  function expect(type, value) {
    const t = consume();
    if (!t || t.type !== type || (value !== undefined && t.value !== value)) {
      throw new SyntaxError(
        `Expected ${type}${value !== undefined ? ' ' + value : ''}, ` +
        `got ${t ? t.type + ' ' + t.value : 'end of input'}`
      );
    }
    return t;
  }

  // Top-level: parse a full expression and assert nothing is left over
  function parseAll() {
    const val = parseOr();
    if (pos < tokens.length) {
      throw new SyntaxError(`Unexpected token: ${tokens[pos].value ?? tokens[pos].type}`);
    }
    return val;
  }

  // OR  →  AND ( '||' AND )*
  function parseOr() {
    let left = parseAnd();
    while (peek()?.type === 'op' && peek()?.value === '||') {
      consume();
      const right = parseAnd();
      left = left || right;
    }
    return left;
  }

  // AND  →  CMP ( '&&' CMP )*
  function parseAnd() {
    let left = parseCmp();
    while (peek()?.type === 'op' && peek()?.value === '&&') {
      consume();
      const right = parseCmp();
      left = left && right;
    }
    return left;
  }

  // CMP  →  UNARY ( op UNARY )*
  const CMP_OPS = new Set(['===', '!==', '==', '!=', '>', '<', '>=', '<=']);
  function parseCmp() {
    let left = parseUnary();
    while (peek()?.type === 'op' && CMP_OPS.has(peek()?.value)) {
      const op = consume().value;
      const right = parseUnary();
      switch (op) {
        case '===': left = left === right; break;
        case '!==': left = left !== right; break;
        case '==':  left = left ==  right; break; // eslint-disable-line eqeqeq
        case '!=':  left = left !=  right; break; // eslint-disable-line eqeqeq
        case '>':   left = left >   right; break;
        case '<':   left = left <   right; break;
        case '>=':  left = left >=  right; break;
        case '<=':  left = left <=  right; break;
      }
    }
    return left;
  }

  // UNARY  →  '!' UNARY | PRIMARY
  function parseUnary() {
    if (peek()?.type === 'op' && peek()?.value === '!') {
      consume();
      return !parseUnary();
    }
    return parsePrimary();
  }

  // PRIMARY  →  '(' EXPR ')' | literal | memberExpr
  function parsePrimary() {
    const t = peek();
    if (!t) throw new SyntaxError('Unexpected end of expression');

    // Grouped sub-expression
    if (t.type === 'op' && t.value === '(') {
      consume();
      const val = parseOr();
      expect('op', ')');
      return val;
    }

    // Literals
    if (t.type === 'number' || t.type === 'string' ||
        t.type === 'boolean' || t.type === 'null') {
      consume();
      return t.value;
    }

    // Identifiers — only 'ctx' is a valid root
    if (t.type === 'identifier') {
      return parseMember();
    }

    throw new SyntaxError(`Unexpected token: ${t.value ?? t.type}`);
  }

  /**
   * MEMBER  →  identifier ( '.' identifier )*
   *
   * Only the root identifier 'ctx' is allowed; arbitrary global names
   * (process, require, global, …) are explicitly rejected so there is no
   * path to the Node.js runtime environment.
   */
  function parseMember() {
    const root = consume(); // identifier token
    if (root.type !== 'identifier') {
      throw new SyntaxError(`Expected identifier, got ${root.type}`);
    }

    if (root.value !== 'ctx') {
      throw new EvalError(
        `Identifier '${root.value}' is not allowed. ` +
        `Only 'ctx' may be used as the root of a member expression.`
      );
    }

    // Walk dot-separated property chain against the ctx object
    let value = ctx;
    while (peek()?.type === 'dot') {
      consume(); // consume '.'
      const prop = consume();
      if (!prop || prop.type !== 'identifier') {
        throw new SyntaxError('Expected property name after \'.\'');
      }
      // Only descend into plain objects/arrays; refuse to traverse prototype
      // properties that could expose dangerous built-ins (constructor, __proto__…)
      if (value === null || value === undefined) {
        value = undefined;
        break;
      }
      if (!Object.prototype.hasOwnProperty.call(value, prop.value)) {
        value = undefined;
        break;
      }
      value = value[prop.value];
    }

    return value;
  }

  return { parseAll };
}

/**
 * evalRule — safely evaluate a rule expression against a context object.
 *
 * @param {string} expr  - rule expression, e.g. 'ctx.amount > 100'
 * @param {object} ctx   - the context object provided by the caller
 * @returns {boolean}
 */
function evalRule(expr, ctx) {
  if (typeof expr !== 'string') throw new TypeError('rule must be a string');
  const tokens = tokenise(expr);
  const parser = createParser(tokens, ctx);
  const result = parser.parseAll();
  return Boolean(result);
}

// ---------------------------------------------------------------------------
// HTTP server
// ---------------------------------------------------------------------------

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    req.on('data', chunk => { data += chunk; });
    req.on('end',  ()    => { resolve(data); });
    req.on('error', reject);
  });
}

function send(res, status, body) {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    'Content-Type':   'application/json',
    'Content-Length': Buffer.byteLength(payload),
  });
  res.end(payload);
}

const server = http.createServer(async (req, res) => {
  if (req.method === 'POST' && req.url === '/check') {
    // ── Read + parse request body ──────────────────────────────────────────
    let body;
    try {
      const raw = await readBody(req);
      body = JSON.parse(raw);
    } catch {
      return send(res, 400, { error: 'Invalid JSON body' });
    }

    const { rule, context } = body;

    if (typeof rule !== 'string' || rule.trim() === '') {
      return send(res, 400, { error: '"rule" must be a non-empty string' });
    }
    if (context === undefined || context === null || typeof context !== 'object') {
      return send(res, 400, { error: '"context" must be a non-null object' });
    }

    // ── Evaluate the rule ──────────────────────────────────────────────────
    let result;
    try {
      result = evalRule(rule, context);
    } catch (err) {
      // SyntaxError  → malformed expression
      // EvalError    → disallowed identifier
      // TypeError    → wrong argument types
      const status = err instanceof SyntaxError ? 400 : 400;
      return send(res, status, { error: `Rule evaluation failed: ${err.message}` });
    }

    return send(res, 200, { result });
  }

  // ── 404 for everything else ────────────────────────────────────────────
  send(res, 404, { error: 'Not found' });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`acme-rules listening on port ${PORT}`);
});

module.exports = { server, evalRule }; // export for testing

