    if (/[0-9]/.test(expr[i]) || (expr[i] === '-' && /[0-9]/.test(expr[i + 1] || ''))) {
      let num = '';
      if (expr[i] === '-') num += expr[i++];
      while (i < expr.length && /[0-9.]/.test(expr[i])) num += expr[i++];
      tokens.push({ type: 'number', value: Number(num) });
      continue;
    }

    // Parentheses
    if (expr[i] === '(') { tokens.push({ type: 'lparen' }); i++; continue; }
    if (expr[i] === ')') { tokens.push({ type: 'rparen' }); i++; continue; }

    // Multi-char operators
    const twoChar = expr.slice(i, i + 2);
    if (['===', '!=='].includes(expr.slice(i, i + 3))) {
      tokens.push({ type: 'op', value: expr.slice(i, i + 3) }); i += 3; continue;
    }
    if (['==', '!=', '<=', '>=', '&&', '||'].includes(twoChar)) {
      tokens.push({ type: 'op', value: twoChar }); i += 2; continue;
    }

    // Single-char operators
    if ('!<>+-*/%'.includes(expr[i])) {
      tokens.push({ type: 'op', value: expr[i] }); i++; continue;
    }

