// app.js — acme-rules Rule Engine
'use strict';

const express = require('express');
const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Safe rule evaluator
//
// WHY NOT new Function() / eval():
//   The reference implementation in docs/RULES_ENGINE.md passes the caller-
//   supplied `rule` string directly into `new Function(...)` and executes it.
//   This is Remote Code Execution (RCE): any client can run arbitrary Node.js
//   code on the server (read files, exfiltrate secrets, spawn processes, etc.).
//   No sandboxing is applied, so process-level isolation is impossible.
//
// WHAT WE SUPPORT INSTEAD:
//   A purpose-built expression parser that covers the documented use cases:
//     • Property access on `ctx`          ctx.amount  /  ctx.user.role
//     • Comparison operators              >  <  >=  <=  ==  !=
//     • Strict equality                   ===  !==
//     • Logical combinators               &&  ||
//     • Unary negation                    !
//     • Parenthesised sub-expressions     (ctx.a > 1 && ctx.b < 2)
//     • String literals                   'admin'  "active"
//     • Numeric literals                  42  3.14
//     • Boolean literals                  true  false
//     • Null / undefined literals         null  undefined
//
//   Anything outside this grammar is rejected with HTTP 422 so there is no
//   accidental fall-through to a code-execution path.
// ---------------------------------------------------------------------------

/**
 * Tokeniser — turns the rule string into a flat token array.
 *
 * Token shapes:
 *   { type: 'NUMBER',     value: <number> }
 *   { type: 'STRING',     value: <string> }
 *   { type: 'BOOLEAN',    value: <boolean> }
 *   { type: 'NULL' }
 *   { type: 'UNDEFINED' }
 *   { type: 'IDENT',      value: <string> }   — dotted path, e.g. "ctx.user.role"
 *   { type: 'OP',         value: <string> }   — operator or punctuation
 */
function tokenise(expr) {
  const tokens = [];
  let i = 0;

  while (i < expr.length) {
    // Skip whitespace
    if (/\s/.test(expr[i])) { i++; continue; }

    // String literal — single or double quoted, no escape sequences needed for
    // the rule use-case, but we handle \" / \' for robustness.
    if (expr[i] === '"' || expr[i] === "'") {
      const quote = expr[i++];
      let str = '';
      while (i < expr.length && expr[i] !== quote) {
        if (expr[i] === '\\' && i + 1 < expr.length) { i++; }
        str += expr[i++];
      }
      if (expr[i] !== quote) throw new Error('Unterminated string literal');
      i++; // consume closing quote
      tokens.push({ type: 'STRING', value: str });
      continue;
    }

    // Numeric literal (integer or decimal, optional leading minus handled as
    // unary in parser)
    if (/[0-9]/.test(expr[i]) || (expr[i] === '.' && /[0-9]/.test(expr[i + 1]))) {
      let num = '';
      while (i < expr.length && /[0-9.]/.test(expr[i])) num += expr[i++];
      tokens.push({ type: 'NUMBER', value: Number(num) });
      continue;
    }

    // Operators & punctuation (longest-match first)
    const twoChar = expr.slice(i, i + 3);
    if (['===', '!=='].includes(twoChar)) {
      tokens.push({ type: 'OP', value: twoChar }); i += 3; continue;
    }
    const twoC = expr.slice(i, i + 2);
    if (['==', '!=', '>=', '<=', '&&', '||'].includes(twoC)) {
      tokens.push({ type: 'OP', value: twoC }); i += 2; continue;
    }
    if (['>', '<', '!', '(', ')'].includes(expr[i])) {
      tokens.push({ type: 'OP', value: expr[i] }); i++; continue;
    }

    // Identifier or keyword (letters, digits, underscores, dots for paths)
    if (/[a-zA-Z_$]/.test(expr[i])) {
      let id = '';
      while (i < expr.length && /[a-zA-Z0-9_$.]/.test(expr[i])) id += expr[i++];
      // Classify keywords
      if (id === 'true')      { tokens.push({ type: 'BOOLEAN',   value: true  }); continue; }
      if (id === 'false')     { tokens.push({ type: 'BOOLEAN',   value: false }); continue; }
      if (id === 'null')      { tokens.push({ type: 'NULL'  }); continue; }
      if (id === 'undefined') { tokens.push({ type: 'UNDEFINED' }); continue; }
      tokens.push({ type: 'IDENT', value: id });
      continue;
    }

    throw new Error(`Unexpected character: ${expr[i]}`);
  }

  return tokens;
}

// ---------------------------------------------------------------------------
// Recursive-descent parser + evaluator
//
// Grammar (lowest → highest precedence):
//   expr     → or
//   or       → and  ( '||' and  )*
//   and      → cmp  ( '&&' cmp  )*
//   cmp      → unary ( ( '===' | '!==' | '==' | '!=' | '>=' | '<=' | '>' | '<' ) unary )?
//   unary    → '!' unary  |  primary
//   primary  → '(' expr ')'  |  literal  |  ident
//   literal  → NUMBER | STRING | BOOLEAN | NULL | UNDEFINED
//   ident    → dotted path resolved against ctx
// ---------------------------------------------------------------------------

function parse(tokens, ctx) {
  let pos = 0;

  function peek()    { return tokens[pos]; }
  function consume() { return tokens[pos++]; }

  function parseExpr()    { return parseOr(); }

  function parseOr() {
    let left = parseAnd();
    while (peek()?.type === 'OP' && peek().value === '||') {
      consume();
      const right = parseAnd();
      left = left || right;
    }
    return left;
  }

  function parseAnd() {
    let left = parseCmp();
    while (peek()?.type === 'OP' && peek().value === '&&') {
      consume();
      const right = parseCmp();
      left = left && right;
    }
    return left;
  }

  function parseCmp() {
    const left = parseUnary();
    const op = peek();
    if (op?.type === 'OP' && ['===','!==','==','!=','>=','<=','>','<'].includes(op.value)) {
      consume();
      const right = parseUnary();
      switch (op.value) {
        case '===': return left === right;
        case '!==': return left !== right;
        case '==':  return left ==  right;  // eslint-disable-line eqeqeq
        case '!=':  return left !=  right;  // eslint-disable-line eqeqeq
        case '>=':  return left >=  right;
        case '<=':  return left <=  right;
        case '>':   return left >   right;
        case '<':   return left <   right;
      }
    }
    return left;
  }

  function parseUnary() {
    if (peek()?.type === 'OP' && peek().value === '!') {
      consume();
      return !parseUnary();
    }
    return parsePrimary();
  }

  function parsePrimary() {
    const tok = peek();
    if (!tok) throw new Error('Unexpected end of expression');

    // Parenthesised sub-expression
    if (tok.type === 'OP' && tok.value === '(') {
      consume();
      const val = parseExpr();
      const closing = consume();
      if (!closing || closing.value !== ')') throw new Error('Expected closing )');
      return val;
    }

    consume(); // claim the token

    if (tok.type === 'NUMBER')    return tok.value;
    if (tok.type === 'STRING')    return tok.value;
    if (tok.type === 'BOOLEAN')   return tok.value;
    if (tok.type === 'NULL')      return null;
    if (tok.type === 'UNDEFINED') return undefined;

    if (tok.type === 'IDENT') {
      // Resolve dotted path against ctx, e.g. "ctx.user.role" → ctx["user"]["role"]
      const parts = tok.value.split('.');
      if (parts[0] !== 'ctx') {
        throw new Error(
          `Identifier must start with 'ctx' (got '${parts[0]}'). ` +
          'Direct access to non-ctx variables is not allowed.'
        );
      }
      // Walk the path; return undefined for missing intermediate keys
      let val = ctx;
      for (const part of parts.slice(1)) {
        if (val === null || val === undefined) return undefined;
        val = val[part];
      }
      return val;
    }

    throw new Error(`Unexpected token: ${JSON.stringify(tok)}`);
  }

  const result = parseExpr();

  if (pos < tokens.length) {
    throw new Error(`Unexpected token after expression: ${JSON.stringify(tokens[pos])}`);
  }

  return result;
}

/**
 * Evaluate a rule expression string against a context object.
 *
 * @param {string} expr  - e.g. 'ctx.amount > 100'
 * @param {object} ctx   - the `context` object from the request body
 * @returns {boolean}
 * @throws  {Error} if the expression is syntactically invalid or uses
 *                  disallowed constructs
 */
function evalRule(expr, ctx) {
  if (typeof expr !== 'string' || expr.trim() === '') {
    throw new Error('rule must be a non-empty string');
  }
  const tokens = tokenise(expr);
  const result = parse(tokens, ctx);
  return Boolean(result);
}

// ---------------------------------------------------------------------------
// POST /check
// ---------------------------------------------------------------------------

/**
 * @route  POST /check
 * @body   { rule: string, context: object }
 *
 * Evaluates `rule` against `context` and returns whether the rule passes.
 *
 * Success 200:
 *   { "result": true | false }
 *
 * Client error 422 — invalid / unparseable rule:
 *   { "error": "Invalid rule", "detail": "<message>" }
 *
 * Client error 400 — missing fields:
 *   { "error": "Bad request", "detail": "<message>" }
 */
app.post('/check', (req, res) => {
  const { rule, context } = req.body ?? {};

  if (typeof rule !== 'string' || rule.trim() === '') {
    return res.status(400).json({
      error:  'Bad request',
      detail: '`rule` must be a non-empty string',
    });
  }
  if (context === undefined || context === null || typeof context !== 'object') {
    return res.status(400).json({
      error:  'Bad request',
      detail: '`context` must be a JSON object',
    });
  }

  try {
    const result = evalRule(rule, context);
    return res.status(200).json({ result });
  } catch (err) {
    return res.status(422).json({
      error:  'Invalid rule',
      detail: err.message,
    });
  }
});

// ---------------------------------------------------------------------------
// Start
// ---------------------------------------------------------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`acme-rules listening on port ${PORT}`));

module.exports = app; // for testing

