import express from "express";

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Safe rule engine
// ---------------------------------------------------------------------------
// Rules are plain JSON objects, NOT arbitrary JS expressions.
//
// Rule schema:
//   { "field": <string>, "op": <operator>, "value": <any> }
//
// Supported operators:
//   Comparison : "=="  "!="  "<"  "<="  ">"  ">="
//   String     : "contains"  "startsWith"  "endsWith"
//   Membership : "in"   (value must be an array)
//               "notIn" (value must be an array)
//
// "field" is a dot-separated path resolved against the request context object.
// Example rule:  { "field": "amount", "op": ">", "value": 100 }
// ---------------------------------------------------------------------------

/**
 * Resolve a dot-separated path against obj.
 * Returns `undefined` for missing keys (never throws).
 *
 * @param {object} obj
 * @param {string} path  e.g. "user.address.zip"
 * @returns {*}
 */
function resolvePath(obj, path) {
  if (typeof path !== "string" || path.trim() === "") {
    return undefined;
  }
  return path.split(".").reduce((cur, key) => {
    if (cur === null || cur === undefined) return undefined;
    return cur[key];
  }, obj);
}

/**
 * Evaluate one rule object against a context object.
 *
 * @param {{ field: string, op: string, value: * }} rule
 * @param {object} ctx  – req.body.context
 * @returns {boolean}
 * @throws {Error} if the rule structure is invalid
 */
function evalRule(rule, ctx) {
  const VALID_OPS = new Set([
    "==", "!=", "<", "<=", ">", ">=",
    "contains", "startsWith", "endsWith",
    "in", "notIn",
  ]);

  if (rule === null || typeof rule !== "object" || Array.isArray(rule)) {
    throw new Error('rule must be a JSON object with "field", "op", and "value"');
  }

  const { field, op, value } = rule;

  if (typeof field !== "string" || field.trim() === "") {
    throw new Error('"field" must be a non-empty string');
  }
  if (!VALID_OPS.has(op)) {
    throw new Error(
      `"op" must be one of: ${[...VALID_OPS].join(", ")}. Received: ${JSON.stringify(op)}`
    );
  }
  if (value === undefined) {
    throw new Error('"value" is required');
  }

  const actual = resolvePath(ctx, field);

  switch (op) {
    // --- Comparison ---
    case "==":  return actual == value;   // intentional loose equality
    case "!=":  return actual != value;
    case "<":   return actual <  value;
    case "<=":  return actual <= value;
    case ">":   return actual >  value;
    case ">=":  return actual >= value;

    // --- String ---
    case "contains": {
      if (typeof actual !== "string") {
        throw new Error(`"contains" requires the field value to be a string; got ${typeof actual}`);
      }
      if (typeof value !== "string") {
        throw new Error('"contains" requires "value" to be a string');
      }
      return actual.includes(value);
    }
    case "startsWith": {
      if (typeof actual !== "string") {
        throw new Error(`"startsWith" requires the field value to be a string; got ${typeof actual}`);
      }
      if (typeof value !== "string") {
        throw new Error('"startsWith" requires "value" to be a string');
      }
      return actual.startsWith(value);
    }
    case "endsWith": {
      if (typeof actual !== "string") {
        throw new Error(`"endsWith" requires the field value to be a string; got ${typeof actual}`);
      }
      if (typeof value !== "string") {
        throw new Error('"endsWith" requires "value" to be a string');
      }
      return actual.endsWith(value);
    }

    // --- Membership ---
    case "in": {
      if (!Array.isArray(value)) {
        throw new Error('"in" requires "value" to be an array');
      }
      return value.includes(actual);
    }
    case "notIn": {
      if (!Array.isArray(value)) {
        throw new Error('"notIn" requires "value" to be an array');
      }
      return !value.includes(actual);
    }

    default:
      // Unreachable given the VALID_OPS guard above, but keeps the
      // linter / exhaustiveness checker happy.
      throw new Error(`Unknown operator: ${op}`);
  }
}

// ---------------------------------------------------------------------------
// POST /check
// ---------------------------------------------------------------------------
// Request body:
//   {
//     "rule":    { "field": "amount", "op": ">", "value": 100 },
//     "context": { "amount": 250, ... }
//   }
//
// Success response  (200):
//   { "result": true | false }
//
// Error response    (400):
//   { "error": "<message>" }
// ---------------------------------------------------------------------------

app.post("/check", (req, res) => {
  const { rule, context } = req.body ?? {};

  if (rule === undefined) {
    return res.status(400).json({ error: '"rule" is required' });
  }
  if (context === undefined || context === null || typeof context !== "object" || Array.isArray(context)) {
    return res.status(400).json({ error: '"context" must be a JSON object' });
  }

  try {
    const result = evalRule(rule, context);
    return res.status(200).json({ result });
  } catch (err) {
    return res.status(400).json({ error: err.message });
  }
});

// ---------------------------------------------------------------------------
// Start
// ---------------------------------------------------------------------------
const PORT = process.env.PORT ?? 3000;
app.listen(PORT, () => {
  console.log(`Rules engine listening on port ${PORT}`);
});

export default app;

