const express = require('express');
const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Safe rule evaluator
//
// Supports a practical subset of expression syntax without resorting to
// eval() or the Function() constructor, both of which would allow arbitrary
// remote code execution by any caller who can reach this endpoint.
//
// Grammar (recursive-descent parser):
//
//   expr        → or
//   or          → and  ( '||' and  )*
//   and         → compare ( '&&' compare )*
//   compare     → add ( ('==' | '!=' | '<=' | '>=' | '<' | '>') add )?
//   add         → mul  ( ('+' | '-') mul  )*
//   mul         → unary ( ('*' | '/' | '%') unary )*
//   unary       → ('!' | '-') unary | primary
//   primary     → NUMBER | STRING | BOOLEAN | NULL | UNDEFINED
//               | '(' expr ')'
//               | IDENTIFIER ( ('.' IDENTIFIER) | ('[' expr ']') )*
//                             ( '(' argList ')' )?         ← method call
//
// Context variable:
//   The top-level identifier 'ctx' resolves to req.body.context.
//   Any other top-level identifier is looked up on that same context object
//   so rules like 'amount > 100' work identically to 'ctx.amount > 100'.
// ---------------------------------------------------------------------------

class RuleEvaluator {
  /**
   * @param {string} expr  - The rule expression string.
   * @param {object} ctx   - The context object (req.body.context).
   */
  constructor(expr, ctx) {
    this.src = expr;
    this.ctx = ctx;
    this.pos = 0;
  }

  // ── Public entry point ────────────────────────────────────────────────────

  evaluate() {
    const result = this._parseExpr();
    this._skipWhitespace();
    if (this.pos < this.src.length) {
      throw new SyntaxError(
        `Unexpected token at position ${this.pos}: '${this.src.slice(this.pos)}'`
      );
    }
    return result;
  }

  // ── Recursive-descent parser ──────────────────────────────────────────────

  _parseExpr() {
    return this._parseOr();
  }

  _parseOr() {
    let left = this._parseAnd();
    while (this._match('||')) {
      const right = this._parseAnd();
      left = left || right;
    }
    return left;
  }

  _parseAnd() {
    let left = this._parseCompare();
    while (this._match('&&')) {
      const right = this._parseCompare();
      left = left && right;
    }
    return left;
  }

  _parseCompare() {
    let left = this._parseAdd();
    for (const op of ['===', '!==', '==', '!=', '<=', '>=', '<', '>']) {
      if (this._match(op)) {
        const right = this._parseAdd();
        switch (op) {
          case '==':
          case '===': return left === right;
          case '!=':
          case '!==': return left !== right;
          case '<':   return left <   right;
          case '>':   return left >   right;
          case '<=':  return left <=  right;
          case '>=':  return left >=  right;
        }
      }
    }
    return left;
  }

  _parseAdd() {
    let left = this._parseMul();
    let op;
    while ((op = this._matchAny(['+', '-']))) {
      const right = this._parseMul();
      left = op === '+' ? left + right : left - right;
    }
    return left;
  }

  _parseMul() {
    let left = this._parseUnary();
    let op;
    while ((op = this._matchAny(['*', '/', '%']))) {
      const right = this._parseUnary();
      if (op === '/') { left = left / right; }
      else if (op === '%') { left = left % right; }
      else { left = left * right; }
    }
    return left;
  }

  _parseUnary() {
    if (this._match('!')) return !this._parseUnary();
    if (this._match('-')) return -this._parseUnary();
    return this._parsePrimary();
  }

  _parsePrimary() {
    this._skipWhitespace();

    // Parenthesised sub-expression
    if (this._match('(')) {
      const val = this._parseExpr();
      this._expect(')');
      return val;
    }

