const express = require('express');
const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Safe rule evaluator
//
// Supports a practical subset of expression syntax without resorting to
// eval() or the Function() constructor, both of which would allow arbitrary
// remote code execution by any caller who can reach this endpoint.
//
// Grammar (recursive-descent parser):
//
//   expr        → or
//   or          → and  ( '||' and  )*
//   and         → compare ( '&&' compare )*
//   compare     → add ( ('==' | '!=' | '<=' | '>=' | '<' | '>') add )?
//   add         → mul  ( ('+' | '-') mul  )*
//   mul         → unary ( ('*' | '/' | '%') unary )*
//   unary       → ('!' | '-') unary | primary
//   primary     → NUMBER | STRING | BOOLEAN | NULL | UNDEFINED
//               | '(' expr ')'
//               | IDENTIFIER ( ('.' IDENTIFIER) | ('[' expr ']') )*
//                             ( '(' argList ')' )?         ← method call
//
// Context variable:
//   The top-level identifier 'ctx' resolves to req.body.context.
//   Any other top-level identifier is looked up on that same context object
//   so rules like 'amount > 100' work identically to 'ctx.amount > 100'.
// ---------------------------------------------------------------------------

class RuleEvaluator {
  /**
   * @param {string} expr  - The rule expression string.
   * @param {object} ctx   - The context object (req.body.context).
   */
  constructor(expr, ctx) {
    this.src = expr;
    this.ctx = ctx;
    this.pos = 0;
  }

  // ── Public entry point ────────────────────────────────────────────────────

  evaluate() {
    const result = this._parseExpr();
    this._skipWhitespace();
    if (this.pos < this.src.length) {
      throw new SyntaxError(
        `Unexpected token at position ${this.pos}: '${this.src.slice(this.pos)}'`
      );
    }
    return result;
  }

  // ── Recursive-descent parser ──────────────────────────────────────────────

  _parseExpr() {
    return this._parseOr();
  }

  _parseOr() {
    let left = this._parseAnd();
    while (this._match('||')) {
      const right = this._parseAnd();
      left = left || right;
    }
    return left;
  }

  _parseAnd() {
    let left = this._parseCompare();
    while (this._match('&&')) {
      const right = this._parseCompare();
      left = left && right;
    }
    return left;
  }

  _parseCompare() {
    let left = this._parseAdd();
    for (const op of ['===', '!==', '==', '!=', '<=', '>=', '<', '>']) {
      if (this._match(op)) {
        const right = this._parseAdd();
        switch (op) {
          case '==':  return left == right;   // eslint-disable-line eqeqeq
          case '===': return left === right;
          case '!=':  return left != right;   // eslint-disable-line eqeqeq
          case '!==':
          case '<':   return left <   right;
          case '>':   return left >   right;
          case '<=':  return left <=  right;
          case '>=':  return left >=  right;
        }
      }
    }
    return left;
  }

  _parseAdd() {
    let left = this._parseMul();
    let op;
    while ((op = this._matchAny(['+', '-']))) {
      const right = this._parseMul();
      left = op === '+' ? left + right : left - right;
    }
    return left;
  }

  _parseMul() {
    let left = this._parseUnary();
    let op;
    while ((op = this._matchAny(['*', '/', '%']))) {
      const right = this._parseUnary();
      if (op === '/') { left = left / right; }
      else if (op === '%') { left = left % right; }
      else { left = left * right; }
    }
    return left;
  }

  _parseUnary() {
    if (this._match('!')) return !this._parseUnary();
    if (this._match('-')) return -this._parseUnary();
    return this._parsePrimary();
  }

  _parsePrimary() {
    this._skipWhitespace();

    // Parenthesised sub-expression
    if (this._match('(')) {
      const val = this._parseExpr();
      this._expect(')');
      return val;
    }

    // String literals  ' … '  or  " … "
    if (this.src[this.pos] === '"' || this.src[this.pos] === "'") {
      return this._parseString();
    }

    // Numeric literal
    if (this._isDigit(this.src[this.pos]) ||
        (this.src[this.pos] === '.' && this._isDigit(this.src[this.pos + 1]))) {
      return this._parseNumber();
    }

    // Keywords and identifiers
    if (this._isAlpha(this.src[this.pos])) {
      return this._parseIdentifierExpr();
    }

    throw new SyntaxError(
      `Unexpected character '${this.src[this.pos]}' at position ${this.pos}`
    );
  }

  // ── Literal parsers ───────────────────────────────────────────────────────

  _parseString() {
    const quote = this.src[this.pos++];
    let str = '';
    while (this.pos < this.src.length && this.src[this.pos] !== quote) {
      if (this.src[this.pos] === '\\') {
        this.pos++;
        const esc = this.src[this.pos++];
        const escapes = { n: '\n', t: '\t', r: '\r', '\\': '\\', "'": "'", '"': '"' };
        str += esc in escapes ? escapes[esc] : esc;
      } else {
        str += this.src[this.pos++];
      }
    }
    if (this.pos >= this.src.length) throw new SyntaxError('Unterminated string literal');
    this.pos++; // closing quote
    return str;
  }

  _parseNumber() {
    const start = this.pos;
    while (this.pos < this.src.length && this._isDigit(this.src[this.pos])) this.pos++;
    if (this.src[this.pos] === '.') {
      this.pos++;
      while (this.pos < this.src.length && this._isDigit(this.src[this.pos])) this.pos++;
    }
    return Number(this.src.slice(start, this.pos));
  }

  // ── Identifier / member / call expressions ────────────────────────────────

  _parseIdentifierExpr() {
    const name = this._readIdentifier();

    // Keywords
    if (name === 'true')      return true;
    if (name === 'false')     return false;
    if (name === 'null')      return null;
    if (name === 'undefined') return undefined;

    // Resolve root: 'ctx' maps to the context object; any other bare name is
    // looked up directly on the context so both 'ctx.amount' and 'amount'
    // work as expected.
    let value = name === 'ctx' ? this.ctx : this._safeGet(this.ctx, name);

    // Chain of  .prop  and  [expr]  accessors, followed by an optional call
    while (true) {
      this._skipWhitespace();
      if (this._match('.')) {
        const prop = this._readIdentifier();
        value = this._safeGet(value, prop);
      } else if (this._match('[')) {
        const key = this._parseExpr();
        this._expect(']');
        value = this._safeGet(value, key);
      } else if (this._match('(')) {
        // Method / function call — only allowed on safe built-in values.
        // We intentionally do NOT allow calling arbitrary functions
        // (e.g. constructors, process methods) from rule expressions.
        throw new SyntaxError(
          'Function/method calls are not permitted in rule expressions'
        );
      } else {
        break;
      }
    }

    return value;
  }

  // ── Safe property access ──────────────────────────────────────────────────

  /**
   * Look up `key` on `obj` while blocking prototype-chain escapes.
   * Keys like '__proto__', 'constructor', and 'prototype' are denied
   * to prevent prototype pollution or access to dangerous built-ins.
   */
  _safeGet(obj, key) {
    const BLOCKED = new Set(['__proto__', 'constructor', 'prototype']);
    if (BLOCKED.has(String(key))) {
      throw new EvalError(`Access to '${key}' is not permitted in rule expressions`);
    }
    if (obj === null || obj === undefined) return undefined;
    return obj[key];
  }

  // ── Tokeniser helpers ─────────────────────────────────────────────────────

  _skipWhitespace() {
    while (this.pos < this.src.length && /\s/.test(this.src[this.pos])) this.pos++;
  }

  /** Consume `token` if it appears at the current position; return boolean. */
  _match(token) {
    this._skipWhitespace();
    if (this.src.startsWith(token, this.pos)) {
      this.pos += token.length;
      return true;
    }
    return false;
  }

  /** Try each token in order; consume and return the first match, or null. */
  _matchAny(tokens) {
    for (const t of tokens) {
      if (this._match(t)) return t;
    }
    return null;
  }

  /** Consume `token` or throw. */
  _expect(token) {
    if (!this._match(token)) {
      throw new SyntaxError(
        `Expected '${token}' at position ${this.pos} but got '${this.src[this.pos]}'`
      );
    }
  }

  _readIdentifier() {
    this._skipWhitespace();
    const start = this.pos;
    while (this.pos < this.src.length && this._isAlphaNumeric(this.src[this.pos])) {
      this.pos++;
    }
    if (this.pos === start) {
      throw new SyntaxError(`Expected identifier at position ${this.pos}`);
    }
    return this.src.slice(start, this.pos);
  }

  _isDigit(ch)       { return ch >= '0' && ch <= '9'; }
  _isAlpha(ch)       { return /[a-zA-Z_$]/.test(ch); }
  _isAlphaNumeric(ch){ return /[a-zA-Z0-9_$]/.test(ch); }
}

// ---------------------------------------------------------------------------
// POST /check
// ---------------------------------------------------------------------------

/**
 * Evaluate a rule expression safely against request context.
 *
 * Request body (JSON):
 *   {
 *     "rule":    "<expression>",   // required — e.g. 'ctx.amount > 100'
 *     "context": { … }            // required — data the rule is evaluated against
 *   }
 *
 * Success response 200:
 *   { "result": true | false }
 *
 * Error responses:
 *   400  Bad Request   — missing/invalid fields, or rule syntax error
 *   500  Internal      — unexpected evaluation error
 */
app.post('/check', (req, res) => {
  const { rule, context } = req.body;

  if (typeof rule !== 'string' || rule.trim() === '') {
    return res.status(400).json({ error: '"rule" must be a non-empty string' });
  }
  if (context === undefined || context === null || typeof context !== 'object') {
    return res.status(400)
